(() => { let towers=[[3,2,1],[],[]],selected=null,moves=0,completed=false; const towerButtons=[...document.querySelectorAll('.tower')],feedback=document.querySelector('#feedback'),movesEl=document.querySelector('#moves'); const render=()=>{towerButtons.forEach((button,index)=>{button.classList.toggle('active',selected===index);button.classList.toggle('target',selected!==null&&index!==selected&&(!towers[index].length||towers[index][towers[index].length-1]>towers[selected][towers[selected].length-1]));const label=['Origen','Auxiliar','Destino'][index];button.setAttribute('aria-label',`${label}: ${towers[index].length} disco${towers[index].length===1?'':'s'}`);button.querySelectorAll('.disk').forEach(d=>d.remove());towers[index].forEach(size=>{const disk=document.createElement('span');disk.className=`disk d${size}`;disk.setAttribute('aria-hidden','true');button.insertBefore(disk,button.firstChild);});});movesEl.textContent=`${moves} / 7`;}; const reset=()=>{towers=[[3,2,1],[],[]];selected=null;moves=0;completed=false;feedback.textContent='Objetivo: llevar los 3 discos a la torre de destino.';render();}; const selectTower=index=>{if(completed)return;if(selected===null){if(!towers[index].length){feedback.textContent='Elegí una torre que tenga discos.';return;}selected=index;feedback.textContent='Ahora elegí la torre de destino.';render();return;}if(selected===index){selected=null;feedback.textContent='Movimiento cancelado.';render();return;}const disk=towers[selected][towers[selected].length-1],target=towers[index][towers[index].length-1];if(target&&target<disk){feedback.textContent='Ese disco es más chico. Probá otra torre.';return;}towers[index].push(towers[selected].pop());selected=null;moves+=1;if(towers[2].length===3){completed=true;feedback.textContent=moves===7?'¡Perfecto! Lo resolviste en el mínimo de movimientos.':`¡Resuelto en ${moves} movimientos! El mínimo era 7.`;}else feedback.textContent='Bien. Seguí buscando el camino.';render();}; towerButtons.forEach(button=>button.addEventListener('click',()=>selectTower(Number(button.dataset.tower))));document.querySelector('#reset').addEventListener('click',reset);render();const context=document.modelContext;if(context?.registerTool){const controller=new AbortController();try{Promise.resolve(context.registerTool({name:'get_hanoi_state',title:'Ver estado de Hanoi',description:'Devuelve el estado actual del desafío Torres de Hanoi.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({towers,moves,completed})},{signal:controller.signal})).catch(()=>{});Promise.resolve(context.registerTool({name:'restart_hanoi',title:'Reiniciar Hanoi',description:'Reinicia el desafío Torres de Hanoi.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{reset();return {towers,moves,completed};}},{signal:controller.signal})).catch(()=>{});}catch(_){}} })();
